update public.sentences set tokens = '[{"surface":"—¿Tu","form_ids":["a7d30e51-dab7-5828-8ce0-997361772399"]},{"surface":"abuelo","form_ids":["3f9c0d75-4ff0-56a1-826d-ca4d31fac059"]},{"surface":"está","form_ids":["73a9f7ae-e3e3-5a91-ab0c-a4e945ace577"]},{"surface":"orgulloso","form_ids":["00700725-2b93-5821-b1d7-ab986637abc1"]},{"surface":"de","form_ids":["4692b8ee-7359-5686-855f-b800ded6906f"]},{"surface":"vos?","form_ids":["97dde827-60cb-586f-ab2a-0b18dd4f9cfb"]},{"surface":"—Sí,","form_ids":["191fd126-be91-54fb-8848-9f3aa180ca5d"]},{"surface":"un montón.","form_ids":["0e2d3462-0979-5991-917d-de0593d4891e"]}]'::jsonb, es = '—¿Tu abuelo está orgulloso de vos? —Sí, un montón.', es_alt = array[]::text[], en_alt = array[]::text[], en = '—Is your grandfather proud of you? —Yes, really proud.' where id = '800b9178-80e5-55c6-b714-98e82e4092be' and updated_at = '2026-09-24 23:20:37.211307+00';
update public.sentences set tokens = '[{"surface":"—¿Tus","form_ids":["b944557e-853c-5039-9d8d-1aeedbc21830"]},{"surface":"abuelos","form_ids":["be95e7d1-b26a-5725-bd27-d956108e5436"]},{"surface":"eran","form_ids":["09a1db9f-90bb-5039-8497-71a18817cb0c"]},{"surface":"italianos?","form_ids":["55a7dcbb-8f61-5abf-bf32-6d89ee8ca880"]},{"surface":"—No,","form_ids":["0de01ef6-29bb-557a-a7e2-f6c1110d951b"]},{"surface":"vinieron","form_ids":["746c0d9f-e3ce-577d-a8f7-cb5debc2e272"]},{"surface":"de","form_ids":["4692b8ee-7359-5686-855f-b800ded6906f"]},{"surface":"España.","form_ids":["722a48e9-f4ce-5d2a-a5af-e34b2da5c1a9"]}]'::jsonb, es = '—¿Tus abuelos eran italianos? —No, vinieron de España.', es_alt = array[]::text[], en_alt = array[]::text[], en = '—Were your grandparents Italian? —No, they came from Spain.' where id = '8e3a4938-493c-5644-82ac-e9fb6a82f8e9' and updated_at = '2026-09-27 09:50:21.28704+00';
