update public.sentences set tokens = '[{"surface":"—¿Cómo","form_ids":["af3a59da-b961-5310-80f6-95b5b4c531bd"]},{"surface":"llegaron?","form_ids":["da7a714f-aee4-5608-8c39-a0034b8fde66"]},{"surface":"—Hicimos dedo.","form_ids":["f1e2db96-741c-57d5-8a6d-42f244b62dc1"]}]'::jsonb, es = '—¿Cómo llegaron? —Hicimos dedo.', es_alt = array[]::text[], en_alt = array[]::text[], en = '—How did you get there? —We hitchhiked.' where id = 'fa109d71-a878-5ec0-96a4-b07ad232f473' and updated_at = '2026-09-26 14:58:24.987833+00';
