update public.sentences set tokens = '[{"surface":"—¿Pediste","form_ids":["e9f5a0c6-d268-5aa2-934a-007f3a3a852b"]},{"surface":"la","form_ids":["ac232d51-6535-5e0e-b91c-2828c7fbacf1","dfa47ecf-a246-5612-8a97-61edafd4f2f8"]},{"surface":"ciudadanía?","form_ids":["eb481952-3b58-505d-888a-aea600e12fc7"]},{"surface":"—Todavía","form_ids":["4b8798ec-a0d1-5238-8d96-a84dfb2ea287"]},{"surface":"no.","form_ids":["0de01ef6-29bb-557a-a7e2-f6c1110d951b"]}]'::jsonb, es = '—¿Pediste la ciudadanía? —Todavía no.', es_alt = array[]::text[], en_alt = array[]::text[], en = '—Did you apply for citizenship? —Not yet.' where id = '9f3e4162-db5a-5f13-9cf1-69d8f77c5bf5' and updated_at = '2026-09-27 02:05:54.401015+00';
update public.sentences set tokens = '[{"surface":"—¿Por qué","form_ids":["039949e8-aa88-5eb4-b0c3-3075132e261c"]},{"surface":"estás","form_ids":["16e35e95-01de-5ae2-96c4-e0c4635babc6"]},{"surface":"tan","form_ids":["c26799df-bfe2-5251-9432-3ea02bf78367"]},{"surface":"orgulloso?","form_ids":["00700725-2b93-5821-b1d7-ab986637abc1"]},{"surface":"—Porque","form_ids":["40af6127-af42-5d18-b58a-15fcbd485b41"]},{"surface":"ganamos","form_ids":["5e58e81c-8ecf-5cac-8921-801363bf2032"]},{"surface":"el","form_ids":["56918598-34c4-5168-8557-335face04c15"]},{"surface":"partido.","form_ids":["e9027347-8030-5339-8e88-84c4872fbb10"]}]'::jsonb, es = '—¿Por qué estás tan orgulloso? —Porque ganamos el partido.', es_alt = array[]::text[], en_alt = array[]::text[], en = '—Why are you so proud? —Because we won the game.' where id = '933a3e7a-b040-516b-b252-dc22b8c6b104' and updated_at = '2026-09-27 02:05:54.401015+00';
